        }

        // Apply preprocessing
        if (config.analysisType == "daily") {
            auto processed = preprocessor.preprocess(browsingData);
            return processed;
        }

        return browsingData;
    }

public:
    DataAnalyzer() {
        config.dataDirectory = "data";
        config.outputDirectory = "reports";
        config.db.host = "localhost";
        config.db.port = 5432;
        config.db.dbname = "enterprise_db";
        config.db.user = "admin";
        config.db.password = "admin123";
        config.analysisType = "daily";
        config.cleanDataType = "all";
        setupDirectories();
    }

    void setConfig(const Config& newConfig) {
        config = newConfig;
    }

    void analyzeData() {
        std::cout << "Starting data analysis process" << std::endl;

        auto chatData = processChatLogs();
        auto transactionData = processTransactionData();
        auto browsingData = processBrowsingLogs();

        // Combine data (simplified)
