// DataPreprocessor class for handling data cleaning operations
class DataPreprocessor {
private:
    // Set to store English stopwords for text processing
    std::set<std::string> stopWords;

    // Configuration structure for the data processor
    struct Config {
        std::string dataDirectory;       // Directory for input data files
        std::string outputDirectory;      // Directory for output files
        struct Database {                 // Database configuration
            std::string host;             // Database host
            int port;                     // Database port
            std::string dbname;           // Database name
            std::string user;             // Database user
            std::string password;         // Database password
        } db;
        struct Analysis {                // Analysis configuration
            std::string timeWindow;       // Time window for analysis (daily/weekly)
            std::string dateRange;        // Date range for analysis
        } analysis;
        struct Cleaning {                // Data cleaning configuration
            bool removeDuplicates;        // Whether to remove duplicate records
            bool handleMissing;           // Whether to handle missing values
            bool standardizeDates;        // Whether to standardize date formats
            bool normalizeText;           // Whether to normalize text data
            bool removeSpecialChars;      // Whether to remove special characters
            bool tokenizeText;            // Whether to tokenize text data
        } cleaning;
    } config;

    // Private method to load stopwords
    bool loadStopWords() {
        // Initialize the stopWords set with common English stopwords
        stopWords = {"i", "me", "my", "myself", "we", "our", "ours", "ourselves", "you", "your", "yours", 
                     "yourself", "yourselves", "he", "him", "his", "himself", "she", "her", "hers", "herself", 
