                     "who", "whom", "this", "that", "these", "those", "am", "is", "are", "was", "were", "be", 
                     "been", "being", "have", "has", "had", "having", "do", "does", "did", "doing", "done", 
                     "am", "being", "let", "get", "got", "gone", "go", "going", "would", "will", "can", "could", 
                     "should", "shall", "must", "may", "might", "need", "needs", "needed", "having", "been", 
                     "being", "do", "does", "doing", "done", "am", "being", "being", "let", "get", "got", 
                     "gone", "go", "going", "would", "will", "can", "could", "should", "shall", "must", 
                     "may", "might", "need", "needs", "needed", "having", "been", "being", "do", "does", 
                     "doing", "done", "am", "being", "being"};
        return true; // Return true to indicate successful loading
    }

public:
    // Constructor to initialize the data preprocessor
    DataPreprocessor() {
        // Set up default configuration
        config.dataDirectory = "data";                  // Default data directory
        config.outputDirectory = "reports";              // Default output directory
        config.db.host = "localhost";                    // Default database host
        config.db.port = 5432;                          // Default database port
        config.db.dbname = "enterprise_db";              // Default database name
        config.db.user = "admin";                        // Default database user
        config.db.password = "admin123";                 // Default database password
        config.analysis.timeWindow = "daily";            // Default time window
        config.analysis.dateRange = "";                  // Default date range
        config.cleaning.removeDuplicates = true;         // Enable duplicate removal
        config.cleaning.handleMissing = true;            // Enable missing value handling
        config.cleaning.standardizeDates = true;         // Enable date standardization
        config.cleaning.normalizeText = true;            // Enable text normalization
        config.cleaning.removeSpecialChars = true;       // Enable special character removal
        config.cleaning.tokenizeText = true;             // Enable text tokenization

        // Load stopwords
        loadStopWords();
    }

    // Public method to get the current configuration
    struct Config getConfig() {
        return config;
    }

    // Method to normalize text by converting to lowercase and removing punctuation
    void normalizeText(std::string& text) {
        if (text.empty()) return; // Return early if text is empty

        // Convert all characters to lowercase
        for (char& c : text) {
            c = std::tolower(c);
        }

        // Remove punctuation characters
        text.erase(std::remove_if(text.begin(), text.end(), [](unsigned char c) {
            return ispunct(c); // Check if character is punctuation
        }), text.end());

        // Remove extra whitespace
        auto start = text.begin();
        while ((start = std::find_if(start, text.end(), [](unsigned char c) { return !isspace(c); })) != text.end()) {
            text.erase(start, std::find_if(start, text.end(), [](unsigned char c) { return !isspace(c); }));
        }
    }

    // Method to remove special characters from text
    void removeSpecialChars(std::string& text) {
        if (text.empty()) return; // Return early if text is empty

        std::string cleaned; // Temporary string to store cleaned text

        // Keep only alphanumeric characters and spaces
        for (char c : text) {
            if (isalnum(c) || isspace(c)) {
                cleaned += c; // Add valid characters to cleaned string
            }
        }

        text = cleaned; // Update the original text with cleaned version
    }

    // Method to tokenize text by splitting into words and filtering stopwords
    std::vector<std::string> tokenizeText(const std::string& text) {
        if (text.empty()) return {}; // Return empty vector if text is empty

        std::vector<std::string> tokens; // Vector to store the tokens

        std::istringstream iss(text); // Create string stream for text
        std::string token; // Temporary string for each token

        // Split text into tokens using space as delimiter
        while (iss >> token) {
            // Filter out tokens that are stopwords or too short
            if (stopWords.find(token) == stopWords.end() && token.size() >= 3) {
                tokens.push_back(token); // Add valid token to tokens vector
            }
        }

        return tokens; // Return the vector of tokens
    }

    // Simplified method to demonstrate duplicate removal
    std::vector<std::string> preprocess(const std::vector<std::string>& data) {
        std::vector<std::string> result; // Vector to store processed data

        if (config.cleaning.removeDuplicates) {
            // Use a set to track seen items and remove duplicates
            std::set<std::string> seen;
            for (const auto& item : data) {
                if (seen.find(item) == seen.end()) {
                    seen.insert(item);
                    result.push_back(item);
                }
            }
        } else {
            // If duplicates are not to be removed, return original data
            result = data;
        }

        if (config.cleaning.handleMissing) {
            // Handle missing values (in a real implementation, this would depend on data format)
            for (auto& item : result) {
                if (item.empty()) {
                    item = "Unknown"; // Replace empty strings with "Unknown"
                }
            }
        }

        return result; // Return processed data
    }
};

