/// <summary>
/// Calculates the factorial of a non-negative integer using recursion.
/// </summary>
/// <param name="n">The non-negative integer for which to calculate the factorial</param>
/// <returns>Returns the factorial of n (n!)</returns>
/// <exception cref="invalid_argument">Thrown when n is negative</exception>
long long factorial(int n) {
    if (n < 0) {
        throw invalid_argument("Factorial is undefined for negative numbers");
    }
    if (n == 0 || n == 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

/// <summary>
/// Checks if a given integer is a prime number.
/// </summary>
/// <param name="n">The integer to check for primality</param>
/// <returns>Returns true if n is prime, false otherwise</returns>
/// <exception cref="invalid_argument">Thrown when n is negative</exception>
bool isPrime(int n) {
    if (n < 0) {
        throw invalid_argument("Prime check is undefined for negative numbers");
    }
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    // Check factors up to the square root of n
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

/// <summary>
/// Generates a Fibonacci sequence of the specified length.
/// </summary>
/// <param name="count">The number of Fibonacci numbers to generate</param>
/// <returns>A vector containing the Fibonacci sequence</returns>
/// <exception cref="out_of_range">Thrown when count is negative</exception>
vector<long long> generateFibonacci(int count) {
    if (count < 0) {
        throw out_of_range("Fibonacci sequence length cannot be negative");
    }
    vector<long long> fib;
    if (count >= 1) {
        fib.push_back(0);
    }
    if (count >= 2) {
        fib.push_back(1);
    }
    for (int i = 2; i < count; i++) {
        fib.push_back(fib[i-1] + fib[i-2]);
    }
    return fib;
}

