/*
 * Text processing utilities class
 * Contains static methods for common text manipulation tasks
 */
class StringUtils {
public:
    /*
     * Converts a string to lowercase
     * @param s - input string to convert
     * @return - string with all characters converted to lowercase
     */
    static std::string toLower(const std::string& s) {
        std::string result = s;
        for (char& c : result) {
            c = std::tolower(c);
        }
        return result;
    }

    /*
     * Removes non-alphanumeric characters from a string
     * @param s - input string
     * @return - string containing only alphanumeric characters
     */
    static std::string removeSpecialChars(const std::string& s) {
        std::string result;
        for (char c : s) {
            if (std::isalnum(c) || c == ' ') {
                result += c;
            }
        }
        return result;
    }

    /*
     * Cleans text by:
     * 1. Converting to lowercase
     * 2. Removing punctuation and special characters
     * 3. Preserving words separated by spaces
     * @param s - input string
     * @return - cleaned string
     */
    static std::string cleanText(const std::string& s) {
        std::string result;
        bool inWord = false;
        for (char c : s) {
            if (std::isspace(c)) {
                if (inWord) {
                    result += ' ';
                    inWord = false;
                }
            } else if (std::ispunct(c) || !std::isprint(c)) {
                continue;
            } else {
                inWord = true;
                result += std::tolower(c);
            }
        }
        return result;
    }

    /*
     * Splits a string into tokens (words) separated by whitespace
     * @param s - input string
     * @return - vector of tokens
     */
    static std::vector<std::string> tokenize(const std::string& s) {
        std::vector<std::string> tokens;
        std::istringstream iss(s);
        std::string token;
        while (iss >> token) {
            tokens.push_back(token);
        }
        return tokens;
    }

    /*
     * Applies lemmatization to tokens using a provided lemma map
     * @param tokens - vector of tokens to lemmatize
     * @param lemmaMap - map from original tokens to their lemmatized forms
     * @return - vector of lemmatized tokens
     */
    static std::vector<std::string> lemmatize(const std::vector<std::string>& tokens, const std::unordered_map<std::string, std::string>& lemmaMap) {
        std::vector<std::string> result;
        for (const auto& token : tokens) {
            auto it = lemmaMap.find(token);
            if (it != lemmaMap.end()) {
                result.push_back(it->second);
            } else {
                result.push_back(token);
            }
        }
        return result;
    }
};

/*
 * Simple database interface class using SQLite
 * Provides methods to execute SQL commands and queries
 */
class Database {
private:
    sqlite3* db; // SQLite database handle
    std::string name; // Database name

public:
    /*
     * Constructor - opens the SQLite database
     * @param name - name/path of the database file
     * @throws std::runtime_error if database cannot be opened
     */
    Database(const std::string& name) {
        int rc = sqlite3_open(name.c_str(), &db);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Cannot open database: " + std::string(sqlite3_errmsg(db)));
        }
        this->name = name;
    }

    /*
     * Destructor - closes the database connection
     */
    ~Database() {
        sqlite3_close(db);
    }

    /*
     * Executes a SQL command (INSERT, UPDATE, DELETE, etc.)
     * @param sql - SQL command to execute
     * @throws std::runtime_error if SQL execution fails
     */
    void execute(const std::string& sql) {
        char* errMsg = nullptr;
        int rc = sqlite3_exec(db, sql.c_str(), nullptr, nullptr, &errMsg);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("SQL error: " + std::string(errMsg));
            sqlite3_free(errMsg);
        }
    }

    /*
     * Executes a SELECT query and returns the results
     * @param sql - SELECT query to execute
     * @return - 2D vector of strings containing query results
     */
    std::vector<std::vector<std::string>> query(const std::string& sql) {
        sqlite3_stmt* stmt = nullptr;
        int rc = sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Prepare failed: " + std::string(sqlite3_errmsg(db)));
        }

        std::vector<std::vector<std::string>> result;
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            int cols = sqlite3_column_count(stmt);
            std::vector<std::string> row;
            for (int i = 0; i < cols; i++) {
                row.push_back(std::string(sqlite3_column_text(stmt, i), sqlite3_column_bytes(stmt, i)));
            }
            result.push_back(row);
        }

        sqlite3_finalize(stmt);
        return result;
    }
};

/*
 * Data preprocessing class
 * Handles cleaning, transformation, and preparation of data for analysis
 */
class DataPreprocessor {
private:
    std::unordered_map<std::string, std::string> lemmaMap; // Map from original tokens to lemmatized forms
    std::string missingValueHandling = "drop"; // Default strategy for handling missing values

public:
    /*
     * Constructor - initializes the preprocessor with a lemma map and missing value handling strategy
     * @param lemmaMap - map containing lemmatization rules
     * @param strategy - method for handling missing values ("drop" or "impute")
     */
    DataPreprocessor(const std::unordered_map<std::string, std::string>& lemmaMap, const std::string& strategy = "drop") {
        this->lemmaMap = lemmaMap;
        this->missingValueHandling = strategy;
    }

    /*
     * Removes stop words from a list of tokens
     * @param tokens - vector of tokens to process
     * @param stopWords - set of stop words to remove
     * @return - vector of tokens without stop words
     */
    std::vector<std::string> removeStopWords(const std::vector<std::string>& tokens, const std::unordered_set<std::string>& stopWords) {
        std::vector<std::string> result;
        for (const auto& token : tokens) {
            if (stopWords.find(token) == stopWords.end()) {
                result.push_back(token);
            }
        }
        return result;
    }

    /*
     * Standardizes customer IDs by converting to lowercase and removing non-alphanumeric characters
     * @param id - customer ID string to standardize
     * @return - standardized customer ID
     */
    std::string standardizeCustomerId(const std::string& id) {
        std::string result = StringUtils::toLower(id);
        result.erase(std::remove_if(result.begin(), result.end(), [](unsigned char ch) {
            return !std::isalnum(ch);
        }), result.end());
        return result;
    }

    /*
     * Standardizes product names by converting to lowercase and removing special characters
     * @param name - product name string to standardize
     * @return - standardized product name
     */
    std::string standardizeProductName(const std::string& name) {
        std::string result = StringUtils::toLower(name);
        std::regex regex("[^a-z0-9 ]+");
        result = std::regex_replace(result, regex, " ");
        return result;
    }

    /*
     * Preprocesses text data by cleaning, tokenizing, removing stop words, and lemmatizing
     * @param text - input text to preprocess
     * @param stopWords - set of stop words to remove
     * @return - vector of processed tokens
     */
    std::vector<std::string> preprocessText(const std::string& text, const std::unordered_set<std::string>& stopWords) {
        std::string cleaned = StringUtils::cleanText(text);
        auto tokens = StringUtils::tokenize(cleaned);
        tokens = removeStopWords(tokens, stopWords);
        auto lemmatized = StringUtils::lemmatize(tokens, lemmaMap);
        return lemmatized;
    }

    /*
     * Processes a record of data by applying various preprocessing steps
     * @param data - map containing data fields
     * @param fileType - type of data ("chat" or "transaction")
     * @return - processed data map
     */
    std::map<std::string, std::string> process(const std::map<std::string, std::string>& data, const std::string& fileType) {
        std::map<std::string, std::string> result = data;

        // Standardize customer IDs if present
        if (result.find("customer_id") != result.end()) {
            result["customer_id"] = standardizeCustomerId(result["customer_id"]);
        }

        // Standardize product names if present
        if (result.find("product") != result.end()) {
            result["product"] = standardizeProductName(result["product"]);
        }

        // Handle missing values (placeholder implementation)
        if (missingValueHandling == "drop") {
            // In C++ we're processing individual records, so we'd need to implement this differently
            // This is just a placeholder for the concept
        }

        // Preprocess text if applicable
        if (fileType == "chat" && result.find("chat_content") != result.end()) {
            std::unordered_set<std::string> stopWords = {"the", "and", "is", "in", "on", "at", "for", "with"};
            auto processed = preprocessText(result["chat_content"], stopWords);
            result["cleaned_content"] = StringUtils::join(processed, " ");
            result["tokens"] = StringUtils::join(processText(result["chat_content"], stopWords), " ");
        }

        return result;
    }
};

/*
 * Data loading class
 * Handles loading of different types of data files
 */
class DataLoader {
private:
    std::string dataDir; // Directory containing data files

public:
    /*
     * Constructor - initializes the data loader with the directory path
     * @param dir - directory containing data files
     */
    DataLoader(const std::string& dir) : dataDir(dir) {}

    /*
     * Loads CSV file and returns records as a vector of maps
     * @param file - path to the CSV file
     * @return - vector of maps representing the records
     */
    std::vector<std::map<std::string, std::string>> loadCSV(const std::string& file) {
        std::vector<std::map<std::string, std::string>> records;
        std::ifstream in(file);
        std::string line;

        if (!in.is_open()) {
            throw std::runtime_error("Cannot open file: " + file);
        }

        std::string header;
        std::getline(in, header);
        std::stringstream ss(header);
        std::string field;
        std::vector<std::string> headers;
        while (ss >> field) {
            headers.push_back(field);
        }

        while (std::getline(in, line)) {
            std::stringstream lineSS(line);
            std::map<std::string, std::string> record;
            for (size_t i = 0; i < headers.size(); i++) {
                std::string value;
                std::getline(lineSS, value, ',');
                record[headers[i]] = value;
            }
            records.push_back(record);
        }

        return records;
    }

    /*
     * Loads JSON file and returns records as a vector of maps
     * @param file - path to the JSON file
     * @return - vector of maps representing the records
     */
    std::vector<std::map<std::string, std::string>> loadJSON(const std::string& file) {
        // Simplified JSON loading - in a real implementation, use a proper JSON library
        std::ifstream in(file);
        std::string jsonStr((std::istreambuf_iterator<char>(in)), '\0');
        Json::Value root;
        Json::CharReaderBuilder builder;
        builder["ignoreComments"] = false;
        Json::CharReader* reader = builder.newCharReader();
        std::string errors;
        bool success = reader->parse(jsonStr.c_str(), jsonStr.c_str() + jsonStr.size(), &root, &errors);
        delete reader;
        if (!success) {
            throw std::runtime_error("JSON parse error: " + errors);
        }

        std::vector<std::map<std::string, std::string>> records;
        if (root.isArray()) {
            for (Json::Value::iterator i = root.begin(); i != root.end(); ++i) {
                std::map<std::string, std::string> record;
                for (Json::Value::MemberIterator it = (*i).begin(); it != (*i).end(); ++it) {
                    record[it.key().asString()] = it.value().asString();
                }
                records.push_back(record);
            }
        } else {
            throw std::runtime_error("JSON document must be an array of objects");
        }

        return records;
    }

    /*
     * Loads data based on file type (simplified implementation)
     * @param fileType - type of data to load ("csv" or "json")
     * @return - vector of records
     */
    std::vector<std::map<std::string, std::string>> loadData(const std::string& fileType) {
        // This would be implemented in a real application
        return std::vector<std::map<std::string, std::string>>();
    }
};

