        double totalSales = 0.0;
        for (double amount : amounts) {
            totalSales += amount;
        }

        int numTransactions = amounts.size();
        double averageTransaction = (numTransactions > 0) ? totalSales / numTransactions : 0.0;

        // Find top selling product
        std::string topProduct = "";
        int maxSales = 0;
        for (const auto& pair : productSales) {
            if (pair.second > maxSales) {
                maxSales = pair.second;
                topProduct = pair.first;
            }
        }

        // Save results to database
        std::string insertSQL = 
            "INSERT INTO summary_reports (report_type, metrics) VALUES ('transactions', '";
            insertSQL += "Total Sales: " + std::to_string(totalSales) + ", ";
            insertSQL += "Avg Transaction: " + std::to_string(averageTransaction) + ", ";
            insertSQL += "Top Product: " + topProduct + "')";

        try {
            db.execute(insertSQL);
        } catch (const std::exception& e) {
            // Handle database error
            std::cerr << "Error inserting report: " << e.what() << std::endl;
        }
    }

